"""Config loader — fail-closed on missing/invalid config."""

from __future__ import annotations

from pathlib import Path

DEFAULTS = {"failure_threshold": 3, "success_threshold": 2, "open_seconds": 30.0}

FAIL_CLOSED = {"failure_threshold": 1, "success_threshold": 10**9, "open_seconds": 1e9}


def load_breaker_config(path: str | None) -> dict:
    if path is None:
        return dict(DEFAULTS)
    p = Path(path)
    if not p.is_file():
        # fail closed: opens immediately after one failure; almost never closes
        return dict(FAIL_CLOSED)
    cfg = dict(DEFAULTS)
    try:
        for raw in p.read_text(encoding="utf-8").splitlines():
            line = raw.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            k, v = k.strip(), v.strip()
            if k in cfg:
                cfg[k] = int(v) if k != "open_seconds" else float(v)
    except Exception:
        return dict(FAIL_CLOSED)
    return cfg

"""CircuitBreaker — full state machine with closed, open, half_open."""

from __future__ import annotations

import time

from service.config import load_breaker_config
from service.state import BreakerState


class CircuitBreaker:
    def __init__(
        self,
        failure_threshold: int,
        success_threshold: int,
        open_seconds: float,
        *,
        clock=None,
    ):
        self.failure_threshold = failure_threshold
        self.success_threshold = success_threshold
        self.open_seconds = open_seconds
        self.clock = clock or time.monotonic
        self.state = BreakerState()

    def mode(self) -> str:
        return self.state.mode

    def allow_request(self) -> bool:
        if self.state.mode == "closed":
            return True
        if self.state.mode == "open":
            # Check if enough time has passed to transition to half_open
            if self.state.opened_at is not None and (
                self.clock() - self.state.opened_at >= self.open_seconds
            ):
                self.state.mode = "half_open"
                self.state.successes = 0
                return True
            return False
        # half_open: allow probe requests
        if self.state.mode == "half_open":
            return True
        return False

    def record_success(self) -> None:
        if self.state.mode == "closed":
            self.state.failures = 0
        elif self.state.mode == "half_open":
            self.state.successes += 1
            if self.state.successes >= self.success_threshold:
                # Transition to closed
                self.state.mode = "closed"
                self.state.failures = 0
                self.state.successes = 0
                self.state.opened_at = None

    def record_failure(self) -> None:
        if self.state.mode == "closed":
            self.state.failures += 1
            if self.state.failures >= self.failure_threshold:
                self.state.mode = "open"
                self.state.opened_at = self.clock()
        elif self.state.mode == "half_open":
            # Any failure in half_open goes straight back to open
            self.state.mode = "open"
            self.state.successes = 0
            self.state.opened_at = self.clock()

    @classmethod
    def from_config(cls, path: str | None = None, *, clock=None) -> "CircuitBreaker":
        cfg = load_breaker_config(path)
        return cls(
            cfg["failure_threshold"],
            cfg["success_threshold"],
            cfg["open_seconds"],
            clock=clock,
        )
